prelude_js:
// L03 的火星车：s1 与 s7 是终止态，r(s1)=+1、r(s7)=+10，其余为 0，γ=1（回合制，
// 有限时域下 γ=1 安全 —— 见 L02 KP3）。本片用的轨迹是 s3 → s2 → s2 → s1 → 终止。
// 所有数字均由独立脚本核算过，未经修饰。
var TRAJ=[[2,0,1],[1,0,1],[1,0,0],[0,1,null]];   // (s, r, s′)，0 起标
function tdRun(alpha,eps){var V=[0,0,0,0,0,0,0],e,i;
  for(e=0;e<eps;e++){for(i=0;i<TRAJ.length;i++){
    var s=TRAJ[i][0],r=TRAJ[i][1],sp=TRAJ[i][2];
    var nx=(sp===null)?0:V[sp];
    V[s]=V[s]+alpha*(r+nx-V[s]);}}
  return V;}

